function hermitepoly = irf_hermitefunction(vvals,nn)
% IRF_HERMITEFUNCTION Compute the Hermite polynomial (physicist's Hermite polynomials) of order n.
%
% Input:
%       vvals - array or matrix of normalized speeds to calculate hermite
%       functions [(v - V_bulk)/v_th,RMS].
%       nn - order of the Hermite polynomial
%
% Output:
%       hermitepoly - Hermite polynomial with the same dimensions as vvals
%
% Notes: Hard coded polynomials are only valid until about order 64.
% Double precision is insufficient for higher order polynomials. Another
% method is needed at higher orders.
% Hard coding polynomials is much faster than default method of computing
% hermite functions (e.g., hermiteH).
%
% Written by D. B. Graham

vvals = double(vvals);
if nn == 0
  hermitepoly = ones(size(vvals));
