elseif nn == 4
  hermitepoly = 16*vvals.^4 - 48*vvals.^2 + 12;
elseif nn == 5
  hermitepoly = 32*vvals.^5 - 160*vvals.^3 + 120*vvals;
elseif nn == 6
  hermitepoly = 64*vvals.^6 - 480*vvals.^4 + 720*vvals.^2 - 120;
